def encode(message):
    """
    Swaps the case of all letters and replaces every vowel with the
    letter that appears 2 places ahead of it in the English alphabet.

    Examples:
    >>> encode('test')
    'TGST'
    >>> encode('This is a message')
    'tHKS KS C MGSSCGG'
    """
    swapped = message.swapcase()
